// MT2009_PLUS_DUNGEON_ZONE_V1 (server-patches/strefy): area attacks on the ground of a dungeon, for the quests -
// Glebie Polnocnego Wiatru (Smiertelny Chlod, lodowe kolce) and Swiatynia Wezy (atak z powierzchni).
//   d.zone_attack(x, y, radius, pct, flat, delay_ms, warn_effect [, strike_effect [, repeat_ms [, tag [, life_ms]]]])
//     x, y, radius in the dungeon's local cells (as d.spawn_mob). A marker (the invisible race ZONE_MARK_VNUM, its
//     client model "warp") stands on the spot and shows warn_effect to everyone who sees it; after delay_ms every
//     living player of the dungeon inside the circle takes pct% of his max HP + flat as real damage (a kill is a
//     real death: CHARACTER::Damage DAMAGE_TYPE_SYSTEM -> Dead, the dungeon's "die" quests run). strike_effect (or
//     "") plays on the marker when somebody is hit. repeat_ms > 0: the zone stays and strikes again every repeat_ms
//     until life_ms (0 = as long as the dungeon). tag: each hit adds 1 to the dungeon flag <tag><player id>.
//   d.zone_hurt(pid, pct, flat): the same real damage to one player of the dungeon (a debuff's tick).
// Everything hurts from an event, never inside the running quest (a death runs quests of its own).
enum { ZONE_MARK_VNUM = 3975, ZONE_SHOW_PULSES = 4, ZONE_LINGER_MS = 2500, ZONE_MIN_REPEAT_MS = 500,
	ZONE_REFRESH_MS = 15000 };

EVENTINFO(dungeon_zone_info)
{
	CDungeon::IdType dungeon_id;
	long map_index;
	int x, y, radius;
	int pct, flat;
	DWORD mark_vid;
	int step;			// 0: show the warning, 1: strike, 2: remove the marker, 3: a new marker (a lasting zone)
	int delay_pulses, repeat_pulses, life_until;	// life_until: pulses from the zone's start (0 = no limit)
	int age, since_refresh;
	char warn[MAX_EFFECT_FILE_NAME];
	char strike[MAX_EFFECT_FILE_NAME];
	char tag[24];

	dungeon_zone_info() : dungeon_id(0), map_index(0), x(0), y(0), radius(0), pct(0), flat(0), mark_vid(0), step(0),
		delay_pulses(0), repeat_pulses(0), life_until(0), age(0), since_refresh(0)
	{
		warn[0] = strike[0] = tag[0] = '\0';
	}
};

static int M2ZoneClamp(int v, int lo, int hi)
{
	return v < lo ? lo : (v > hi ? hi : v);
}

static int M2ZonePulses(int ms)
{
	const int p = (int) ((long long) M2ZoneClamp(ms, 0, 3600 * 1000) * passes_per_sec / 1000);
	return p > 0 ? p : 1;
}

static void M2ZoneHurt(LPCHARACTER ch, int pct, int flat)
{
	if (!ch || !ch->IsPC() || ch->IsDead() || !ch->GetDesc())
		return;
	long long dam = (long long) ch->GetMaxHP() * pct / 100 + flat;
	if (dam <= 0)
		return;
	if (dam > 2000000000LL)
		dam = 2000000000LL;
	ch->Damage(NULL, (int) dam, DAMAGE_TYPE_SYSTEM);
}

struct FM2ZoneVictims
{
	long map_index;
	int x, y, radius;
	std::vector<DWORD> vids;
	void operator()(LPCHARACTER ch)
	{
		if (!ch || !ch->IsPC() || ch->IsDead() || ch->GetMapIndex() != map_index)
			return;
		if (DISTANCE_APPROX(ch->GetX() - x, ch->GetY() - y) <= radius)
			vids.push_back(ch->GetVID());
	}
};

EVENTFUNC(dungeon_zone_event)
{
	dungeon_zone_info* info = dynamic_cast<dungeon_zone_info*>(event->info);
	if (!info)
		return 0;
	LPDUNGEON pDungeon = CDungeonManager::instance().Find(info->dungeon_id);
	LPCHARACTER mark = info->mark_vid ? CHARACTER_MANAGER::instance().Find(info->mark_vid) : NULL;
	if (mark && (mark->GetRaceNum() != ZONE_MARK_VNUM || mark->GetMapIndex() != info->map_index))
		mark = NULL;
	if (!pDungeon || pDungeon->GetMapIndex() != info->map_index)
	{
		if (mark)
			M2_DESTROY_CHARACTER(mark);
		return 0;
	}
	if (info->step == 0)
	{
		if (mark && info->warn[0])
			mark->SpecificEffectPacket(info->warn);
		info->step = 1;
		info->age += info->delay_pulses;
		return info->delay_pulses;
	}
	if (info->step == 3)
	{
		// a lasting zone: its effect again for whoever came near (or back) since - shown a few pulses after
		// the new marker, then the strikes go on
		if (mark && info->warn[0])
			mark->SpecificEffectPacket(info->warn);
		info->step = 1;
		info->age += info->repeat_pulses;
		return info->repeat_pulses;
	}
	if (info->step == 1)
	{
		FM2ZoneVictims f;
		f.map_index = info->map_index;
		f.x = info->x;
		f.y = info->y;
		f.radius = info->radius;
		f = pDungeon->ForEachMember(f);
		if (!f.vids.empty() && mark && info->strike[0])
			mark->SpecificEffectPacket(info->strike);
		// a death may run quests that change the dungeon's members: every victim is looked up again
		for (size_t i = 0; i < f.vids.size(); ++i)
		{
			LPCHARACTER ch = CHARACTER_MANAGER::instance().Find(f.vids[i]);
			if (!ch || !ch->IsPC() || ch->IsDead() || ch->GetMapIndex() != info->map_index)
				continue;
			const DWORD pid = ch->GetPlayerID();
			M2ZoneHurt(ch, info->pct, info->flat);
			if (info->tag[0])
			{
				LPDUNGEON d2 = CDungeonManager::instance().Find(info->dungeon_id);
				if (d2)
				{
					char flag[48];
					snprintf(flag, sizeof(flag), "%s%u", info->tag, pid);
					d2->SetFlag(flag, d2->GetFlag(flag) + 1);
				}
			}
		}
		if (info->repeat_pulses > 0 && (info->life_until == 0 || info->age + info->repeat_pulses < info->life_until))
		{
			// the client draws an effect for the characters it has; a zone that lasts gets a new marker every
			// ZONE_REFRESH_MS, so a player who walks in from afar (or logs back in) sees it too
			info->since_refresh += info->repeat_pulses;
			if (info->mark_vid && info->since_refresh >= M2ZonePulses(ZONE_REFRESH_MS))
			{
				info->since_refresh = 0;
				if (mark)
					M2_DESTROY_CHARACTER(mark);
				LPCHARACTER fresh = CHARACTER_MANAGER::instance().SpawnMob(ZONE_MARK_VNUM, info->map_index, info->x, info->y, 0);
				info->mark_vid = fresh ? fresh->GetVID() : 0;
				info->step = 3;
				info->age += ZONE_SHOW_PULSES;
				return ZONE_SHOW_PULSES;
			}
			info->age += info->repeat_pulses;
			return info->repeat_pulses;
		}
		info->step = 2;
		return M2ZonePulses(ZONE_LINGER_MS);
	}
	if (mark)
		M2_DESTROY_CHARACTER(mark);
	return 0;
}

ALUA(dungeon_zone_attack)
{
	CQuestManager& q = CQuestManager::instance();
	LPDUNGEON pDungeon = q.GetCurrentDungeon();
	if (!pDungeon || !lua_isnumber(L, 1) || !lua_isnumber(L, 2) || !lua_isnumber(L, 3))
	{
		lua_pushboolean(L, 0);
		return 1;
	}
	LPSECTREE_MAP pMap = SECTREE_MANAGER::instance().GetMap(pDungeon->GetMapIndex());
	if (!pMap)
	{
		lua_pushboolean(L, 0);
		return 1;
	}
	dungeon_zone_info* info = AllocEventInfo<dungeon_zone_info>();
	info->dungeon_id = pDungeon->GetId();
	info->map_index = pDungeon->GetMapIndex();
	info->x = pMap->m_setting.iBaseX + (int) lua_tonumber(L, 1) * 100;
	info->y = pMap->m_setting.iBaseY + (int) lua_tonumber(L, 2) * 100;
	info->radius = M2ZoneClamp((int) (lua_tonumber(L, 3) * 100), 50, 5000);
	info->pct = M2ZoneClamp((int) lua_tonumber(L, 4), 0, 100);
	info->flat = M2ZoneClamp((int) lua_tonumber(L, 5), 0, 2000000000);
	info->delay_pulses = M2ZonePulses((int) lua_tonumber(L, 6));
	if (lua_isstring(L, 7))
		strlcpy(info->warn, lua_tostring(L, 7), sizeof(info->warn));
	if (lua_isstring(L, 8))
		strlcpy(info->strike, lua_tostring(L, 8), sizeof(info->strike));
	const int repeat_ms = lua_isnumber(L, 9) ? (int) lua_tonumber(L, 9) : 0;
	if (repeat_ms > 0)
		info->repeat_pulses = M2ZonePulses(repeat_ms < ZONE_MIN_REPEAT_MS ? ZONE_MIN_REPEAT_MS : repeat_ms);
	if (lua_isstring(L, 10) && !lua_isnumber(L, 10))
		strlcpy(info->tag, lua_tostring(L, 10), sizeof(info->tag));
	const int life_ms = lua_isnumber(L, 11) ? (int) lua_tonumber(L, 11) : 0;
	if (life_ms > 0)
		info->life_until = M2ZonePulses(life_ms);
	if (CMobManager::instance().Get(ZONE_MARK_VNUM))
	{
		LPCHARACTER mark = CHARACTER_MANAGER::instance().SpawnMob(ZONE_MARK_VNUM, info->map_index, info->x, info->y, 0);
		if (mark)
			info->mark_vid = mark->GetVID();
	}
	// the warning a few pulses after the marker, so every client has drawn it before its effect comes
	event_create(dungeon_zone_event, info, ZONE_SHOW_PULSES);
	lua_pushboolean(L, 1);
	return 1;
}

EVENTINFO(dungeon_zone_hurt_info)
{
	CDungeon::IdType dungeon_id;
	DWORD pid;
	int pct, flat;
	dungeon_zone_hurt_info() : dungeon_id(0), pid(0), pct(0), flat(0) {}
};

EVENTFUNC(dungeon_zone_hurt_event)
{
	dungeon_zone_hurt_info* info = dynamic_cast<dungeon_zone_hurt_info*>(event->info);
	if (!info)
		return 0;
	LPDUNGEON pDungeon = CDungeonManager::instance().Find(info->dungeon_id);
	LPCHARACTER ch = CHARACTER_MANAGER::instance().FindByPID(info->pid);
	if (pDungeon && ch && ch->GetMapIndex() == pDungeon->GetMapIndex())
		M2ZoneHurt(ch, info->pct, info->flat);
	return 0;
}

ALUA(dungeon_zone_hurt)
{
	LPDUNGEON pDungeon = CQuestManager::instance().GetCurrentDungeon();
	if (!pDungeon || !lua_isnumber(L, 1))
	{
		lua_pushboolean(L, 0);
		return 1;
	}
	dungeon_zone_hurt_info* info = AllocEventInfo<dungeon_zone_hurt_info>();
	info->dungeon_id = pDungeon->GetId();
	info->pid = (DWORD) lua_tonumber(L, 1);
	info->pct = M2ZoneClamp((int) lua_tonumber(L, 2), 0, 100);
	info->flat = M2ZoneClamp((int) lua_tonumber(L, 3), 0, 2000000000);
	event_create(dungeon_zone_hurt_event, info, 1);
	lua_pushboolean(L, 1);
	return 1;
}

